import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID as uid} from 'node:crypto';
import {readFile,writeFile} from 'node:fs/promises';
import {fifthDatabase,read,write,type Fifth} from '../support/h5-018-fifth-isolated.ts';
import {paymentFixture} from '../support/h3-payment-fixtures.ts';
import {allocationFixture} from '../support/h3-allocation-fixtures.ts';
import {providerPaymentFixture} from '../support/h3-provider-payment-fixtures.ts';
import {ownEconomicsFixture} from '../support/h3-own-economics-fixtures.ts';
import {invoiceFixture} from '../support/h3-invoice-fixtures.ts';
import {depositFixture} from '../support/h4-deposit-fixtures.ts';
import {refundFixture} from '../support/h6-007-refund-fixtures.ts';
import {closureCommands} from '../support/h5-closure-fixtures.ts';
import {H3011ProviderPaymentAdapter} from '../../src/infrastructure/postgres/h3-provider-payment-adapter.ts';
import {verifyAuth} from '../../src/application/verified-auth.ts';
let h:Fifth;const observed:Record<string,unknown>={};
before(async()=>{h=await fifthDatabase('independent_h6005',61403);});
after(async()=>{await writeFile(process.env.AUDIT_OUT!+'/observed.json',JSON.stringify(observed,null,2)+'\n');if(h){await writeFile(process.env.AUDIT_OUT!+'/postgres.log',await readFile(h.temporary+'/postgres.log'));await h.close();}});
async function snapshot(){const names=await h.observer`select tablename from pg_tables where schemaname='crm_private' and tablename like 'b05_%' order by tablename`;const out:Record<string,unknown>={};for(const {tablename:t} of names)out[t]=(await h.observer.unsafe(`select coalesce(jsonb_agg(x order by x::text),'[]') v from(select to_jsonb(t) x from crm_private.${t} t)q`))[0]!.v;return out;}
test('AUD005-01 forecast absent, duplicate movement, correspondence217 of503 and unverified funds denied',async()=>{
 const f=await paymentFixture(h,'503.00',true,'1006.00');assert.equal(await h.payments.read(await h.auth(),read,f.paymentId),null);
 await h.payments.apply(await h.auth(),write,f.detect);assert.equal((await h.payments.read(await h.auth(),read,f.paymentId))!.summary.grossReceived,null);assert.equal((await h.payments.apply(await h.auth(),write,f.detect)).replayed,true);
 await h.payments.apply(await h.auth(),write,await f.receive());const q=await f.propose(2,'217.00');await h.payments.apply(await h.auth(),write,q);assert.equal((await h.payments.read(await h.auth(),read,f.paymentId))!.summary.verifiedCorrespondence,'0.00');await h.payments.apply(await h.auth(),write,await f.verify(q));assert.equal((await h.payments.read(await h.auth(),read,f.paymentId))!.summary.verifiedCorrespondence,'217.00');
 const a=await allocationFixture(h,'503.00','217.00','verified','1006.00');await assert.rejects(h.allocations.apply(await h.auth(),write,await a.assign('218.00')));await h.allocations.apply(await h.auth(),write,await a.assign('217.00'));assert.equal((await a.see()).summary.assigned,'217.00');observed.A01={payment:await h.payments.read(await h.auth(),read,f.paymentId),funds:await a.see()};
});
test('AUD005-02 supplier307 fee71 cannot mix; actual payment before invoice; correct later original closes only documentary; discrepancy invalidates',async()=>{
 const f=await providerPaymentFixture(h,'401.00','307.00');await h.providerPayments.apply(await h.auth(),write,await f.open());const a=await f.assign('307.00'),fee=await f.su.assign('71.00','307.00','fee');await assert.rejects(h.suplidos.apply(await h.auth(),write,await f.su.fundsCommand([fee.allocationId!])));const q=await f.movement([await f.portion(a)],'307.00');await h.providerPayments.apply(await h.auth(),write,q);
 assert.equal((await f.view())!.paid,'307.00');assert.ok((await f.su.see())!.pending.includes('invoice'));assert.equal((await f.su.funds.see()).summary.consumed,'307.00');assert.equal((await f.su.funds.see()).summary.byPurpose.fee!.consumed,'0.00');
 const c=await closureCommands(h,f.su.bookingId);await c.run(await c.command('economic',{}, {serviceApplicability:[{serviceId:f.basis.serviceId,suplido:true,deposit:false,ownEconomics:false,reason:'SYNTHETIC external supplier scope'}]}));assert.equal((await c.view()).assessments.economic!.criteria.find(x=>x.id==='supplier-documents')!.result,'pending');
 await h.suplidos.apply(await h.auth(),write,await f.su.attachInvoice(4));await h.suplidos.apply(await h.auth(),write,await f.su.command('evaluate'));observed.A02BeforeResolution=await f.su.see();assert.equal((await f.su.see())!.status,'Documentalmente resuelto');assert.equal((await f.su.see())!.evaluation!.fiscalValidation,false);assert.equal((await c.view()).jointClosure.current,false);
 await h.payments.apply(await h.auth(),write,await f.su.funds.discrepancy(4,'0.00','10.00'));await h.suplidos.apply(await h.auth(),write,await f.su.command('evaluate'));assert.notEqual((await f.su.see())!.status,'Documentalmente resuelto');observed.A02={supplier:await f.view(),suplido:await f.su.see(),funds:await f.su.funds.see()};
});
test('AUD005-03 reviewed actual recipient or amount mismatch remains unlinked, internal service cannot create external invoice',async()=>{
 const ref=await invoiceFixture(h);for(const wrong of [{recipientId:ref.basis.recipientId},{amount:'100.02'}]){const f=await invoiceFixture(h);await h.invoices.apply(await h.auth(),write,await f.need());const d=await f.document(wrong);await h.invoices.apply(await h.auth(),write,await f.receive(d));await h.invoices.apply(await h.auth(),write,await f.review());assert.equal((await f.state())!.status,'Incidencia');assert.equal((await f.state())!.document!.amount,d.amount);assert.equal((await f.state())!.document!.recipientId,d.recipientId);const before=await snapshot();await assert.rejects(h.invoices.apply(await h.auth(),write,await f.link()));assert.deepEqual(await snapshot(),before);observed['A03-'+Object.keys(wrong)[0]]=await f.state();}
 const internal=await invoiceFixture(h,'internal');await assert.rejects(h.invoices.apply(await h.auth(),write,await internal.need()));assert.equal(await internal.state(),null);
});
test('AUD005-04 deferred T07 failure rollback, retry after lost response, operation conflict and reauthorization',async()=>{
 const f=await providerPaymentFixture(h,'89.00','53.00');await h.providerPayments.apply(await h.auth(),write,await f.open());const a=await f.assign('53.00'),q=await f.movement([await f.portion(a)],'53.00'),before=await snapshot();
 await h.admin.unsafe("create function crm_private.audit6005_failure()returns trigger language plpgsql as $$begin raise exception 'AUDIT005_DEFERRED_FAULT';end$$;create constraint trigger audit6005_failure after insert on crm_private.b05_provider_payment_operations deferrable initially deferred for each row execute function crm_private.audit6005_failure()");
 try{await assert.rejects(h.providerPayments.apply(await h.auth(),write,q));assert.deepEqual(await snapshot(),before);}finally{await h.admin.unsafe('drop trigger audit6005_failure on crm_private.b05_provider_payment_operations;drop function crm_private.audit6005_failure()');}
 const lost={begin:async(o:any,w:any)=>{await h.runtime.begin(o,w);throw Error('AUDIT005_RESPONSE_LOSS');}} as unknown as typeof h.runtime;await assert.rejects(new H3011ProviderPaymentAdapter(lost,h.f1,h.f2).apply(await h.auth(),write,q));assert.equal((await f.view())!.paid,'53.00');const committed=await snapshot();assert.equal((await h.providerPayments.apply(await h.auth(),write,q)).replayed,true);assert.deepEqual(await snapshot(),committed);
 const alien=await verifyAuth({verify:async()=>({subject:uid(),sessionId:uid(),passwordVerified:true,mfaVerified:true})},uid());await assert.rejects(h.providerPayments.apply(alien,write,q));assert.deepEqual(await snapshot(),committed);await assert.rejects(h.providerPayments.apply(await h.auth(),write,await f.attest({...q,reason:'SYNTHETIC changed operation content'})));assert.deepEqual(await snapshot(),committed);observed.A04={supplier:await f.view(),funds:await f.su.funds.see()};
});
test('AUD005-05 own margin excludes client money, unknown tax and extra costs remain pending; exact Tarari own values',async()=>{
 const f=await ownEconomicsFixture(h);await h.ownEconomics.apply(await h.auth(),write,await f.command());let v=(await f.see())!;assert.equal(v.computed.totals.real.profit,'80.00');const input=structuredClone(f.input);input.costs[0]!.phases.real.input=null;input.tarari=['included2','extra25','extra50'].map(kind=>({id:uid(),serviceId:f.b.detail.services[0]!.id,unitRevisionId:f.unit.revision,pricingFormRevisionId:f.form.revision,kind})) as any;await h.ownEconomics.apply(await h.auth(),write,await f.command({input}));v=(await f.see())!;assert.equal(v.computed.totals.real.profit,null);assert.equal(v.computed.costs[0]!.phases.real.fact.tax,null);assert.equal(v.computed.costs[0]!.phases.real.fact.vat,'unknown');assert.deepEqual(v.computed.tarari.map(x=>x.commercial),['15.00','175.00','325.00']);assert.deepEqual(v.computed.tarari.map(x=>x.cost),['3.80',null,null]);for(const x of v.computed.tarari){assert.equal(x.provider,null);assert.equal(x.suplido,null);assert.equal(x.internalInvoice,null);}observed.A05=v;
});
test('AUD005-06 refund200 actual83 leaves117 and preserves gross; incident closure does not execute remaining',async()=>{
 const f=await refundFixture(h);await f.run(await f.determine());await(await f.approval(await f.authorization())).execute();await f.run(await f.movement('83.00'));assert.equal((await f.view()).executed,'83.00');assert.equal((await f.view()).pendingRight,'117.00');const inc=await f.incident();await h.incidents.apply(await h.auth(),write,await inc.resolve());assert.equal((await f.view()).pendingRight,'117.00');assert.equal((await f.a.see()).summary.received,'200.00');observed.A06=await f.view();
});
test('AUD005-07 provider custody100 retained23 leaves77 unpaid; unknown deposit is not zero',async()=>{
 const f=await depositFixture(h);await f.run(await f.command('open'));assert.equal((await f.view()).applicability,'unknown');await f.run(await f.command('applicability',{applicability:'required',conditions:{catalogRevisionId:f.b.detail.services[0]!.serviceRevisionId,terms:f.terms,condition:f.terms.text}}));await f.run(await f.command('require',{requirement:{amount:'100.00',recipientId:f.provider.id,due:'2026-10-20',condition:f.terms.text}}));await f.run(await f.delivery());await f.run(await f.evaluate());await(await f.approval(await f.determination('23.00'))).execute();await f.run(await f.fact('retain','23.00','0.00'));const v=await f.view();assert.equal(v.amounts.returned,'0.00');assert.equal(v.amounts.pendingReturn,'77.00');observed.A07=v;
});
test('AUD005-08 cross Booking denial, private CRUD forbidden and no synthetic fiscal attributes accepted',async()=>{
 const f=await providerPaymentFixture(h);await h.providerPayments.apply(await h.auth(),write,await f.open());const q=await f.command('confirm',{confirmedAmount:'500.00'}),before=await snapshot();await assert.rejects(h.providerPayments.apply(await h.auth(),write,await f.attest({...q,bookingId:uid()})));assert.equal(await h.providerPayments.read(await h.auth(),read,f.id,uid()),null);await assert.rejects(h.providerPayments.apply(await h.auth(),write,await f.attest({...q,fiscalNumber:'SYNTHETIC-INVALID'} as any)));for(const role of ['crm_h0_runtime','anon','authenticated']){const db=h.connect(role);await assert.rejects(db.unsafe('select * from crm_private.b05_provider_payments'));await assert.rejects(db.unsafe('delete from crm_private.b05_provider_payments where false'));await db.end();}assert.deepEqual(await snapshot(),before);observed.A08={denials:9};
});
